class list {
public:
    typedef _List_node<T> Node;
    typedef _List_iterator<T, T &, T *> iterator;
    Node *_M_node;
    Node *_M_create_node(const T &value) { Node *node = simple_alloc<Node, my_alloc>::allocate(1); construct(&node->_M_data, value); return node; }
    iterator insert(iterator position, const T &value) {
