        node->_M_next = position._M_node;
        node->_M_prev = position._M_node->_M_prev;
        static_cast<Node *>(position._M_node->_M_prev)->_M_next = node;
        position._M_node->_M_prev = node;
        return node;
    }
    template<class InputIterator>
